101	 *
102	 * The field name still needs JSON-path escaping so special characters remain
103	 * inside the quoted key. SQL safety comes from passing the returned path through
104	 * Drizzle's `sql` templates as a value, never as raw SQL.
105	 */
106	export function buildSafeJsonPath(field: string): string {
107	  return `$."${escapeJsonPathKey(field)}"`;
