118	/**
119	 * Combines multiple filter conditions using their associated logic operators (AND/OR).
120	 *
121	 * @param filterConditions - Array of conditions with their logic operators
122	 * @returns A single SQL fragment combining all conditions, or null if empty
123	 */
124	export function combineFilterConditions(
125	  filterConditions: FilterConditionWithOperator[],
126	): SQL<unknown> | null {
127	  if (filterConditions.length === 0) {
128	    return null;
129	  }
130	
131	  if (filterConditions.length === 1) {
132	    return filterConditions[0].condition;
133	  }
134	
135	  return filterConditions.reduce((acc, { condition: cond, logicOperator }, idx) => {
136	    if (idx === 0) {
137	      return cond;
138	    }
139	    return logicOperator === 'OR' ? sql`${acc} OR ${cond}` : sql`${acc} AND ${cond}`;
140	  }, filterConditions[0].condition);
141	}
